function getLang(hass) {
  return (hass?.locale?.language || hass?.language || "en").toLowerCase().replace("_","-");
}
function tr(hass, idx) {
  const l = getLang(hass);
  const s = STRINGS[l] || STRINGS[l.split("-")[0]] || STRINGS.en;
  return s[idx] ?? STRINGS.en[idx];
}

